<?php
declare(strict_types=1);
namespace App\Interface\Http\Arena\Controller;
use App\Application\Arena\DTO\Request\CreateDuelRequestDto;use App\Application\Arena\DTO\Request\SubjectsDuelRequestDto;use App\Application\Arena\Mapper\DuelResponseMapper;use App\Application\Arena\Service\DuelLifecycleService;use App\Application\Arena\Service\GetDuelService;use App\Application\Arena\Service\ListArenaRoomsService;use App\Application\Arena\Service\ListArenaSubjectsService;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Http\ApiResponseFactory;use App\Interface\Http\Identity\IdentityRequestFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class ArenaController { public function __construct(private readonly AuthService $auth,private readonly DuelLifecycleService $lifecycle,private readonly GetDuelService $get,private readonly ListArenaRoomsService $rooms,private readonly ListArenaSubjectsService $subjects,private readonly DuelResponseMapper $mapper,private readonly ApiResponseFactory $responses){} private function user(ServerRequestInterface $r):string{return $this->auth->currentUser((new IdentityRequestFactory())->accessToken($r))->id;} private function ok(ServerRequestInterface $r,ResponseInterface $s,mixed $d,int $status=200):ResponseInterface{return $this->responses->success($s,$d,(string)$r->getAttribute("request_id"),$status);} private function page(ServerRequestInterface $r,ResponseInterface $s,array $p):ResponseInterface{return $this->responses->paginated($s,$p["items"],(string)$r->getAttribute("request_id"),$p["page"],$p["perPage"],$p["total"]);} public function create(ServerRequestInterface $r,ResponseInterface $s,CreateDuelRequestDto $v):ResponseInterface{$d=$this->lifecycle->create($this->user($r),$v->maxPlayers,$v->subjectsPerPlayer,$v->questionCount,$v->questionSeconds,$v->visibility);return $this->ok($r,$s,$this->mapper->map($d),201);} public function join(ServerRequestInterface $r,ResponseInterface $s,string $code):ResponseInterface{return $this->ok($r,$s,$this->mapper->map($this->lifecycle->join($code,$this->user($r))));} public function joinPublic(ServerRequestInterface $r,ResponseInterface $s,string $id):ResponseInterface{return $this->ok($r,$s,$this->mapper->map($this->lifecycle->joinPublic($id,$this->user($r))));} public function get(ServerRequestInterface $r,ResponseInterface $s,string $id):ResponseInterface{$d=$this->get->get($id,$this->user($r));return $d?$this->ok($r,$s,$d):$this->responses->problem($s,"RESOURCE_NOT_FOUND","Sala não encontrada.",404,(string)$r->getAttribute("request_id"));} public function publicRooms(ServerRequestInterface $r,ResponseInterface $s,int $page,int $per):ResponseInterface{$this->user($r);return $this->page($r,$s,$this->rooms->public($page,$per));} public function privateRooms(ServerRequestInterface $r,ResponseInterface $s,int $page,int $per):ResponseInterface{return $this->page($r,$s,$this->rooms->privateCreatedBy($this->user($r),$page,$per));} public function listSubjects(ServerRequestInterface $r,ResponseInterface $s,int $page,int $per):ResponseInterface{$this->user($r);return $this->page($r,$s,$this->subjects->list($page,$per));} public function subjects(ServerRequestInterface $r,ResponseInterface $s,string $id,SubjectsDuelRequestDto $v):ResponseInterface{return $this->ok($r,$s,$this->mapper->map($this->lifecycle->ready($id,$this->user($r),$v->taxonomySubjectIds)));} public function remove(ServerRequestInterface $r,ResponseInterface $s,string $id):ResponseInterface{$this->lifecycle->remove($id,$this->user($r));return $this->ok($r,$s,['removed'=>true]);} public function start(ServerRequestInterface $r,ResponseInterface $s,string $id):ResponseInterface{$userId=$this->user($r);$this->lifecycle->start($id,$userId);return $this->ok($r,$s,$this->get->get($id,$userId));} }
